            const angle = (i * 2 * Math.PI / colorCount) + baseRotation;
            const baseColor = baseColors[i % baseColors.length];
            
            const lab = new LabColor();
            lab.l = Math.min(99, Math.max(60, baseColor.l + lightnessBias));
            
