                {`${''}interface Transform {
    type: 'unary' | 'splitter' | 'remove';
    apply: (points: Point[]) => Point[];
}

class Cell {
    private points: Point[] = [{ position: 0 }];
    private operations: Transform[] = [];

    addTransform(transform: Transform) {
        this.operations.push(transform);
        this.recalculate();
    }

    private recalculate() {
        let currentPoints = [{ position: 0 }];
        for (const op of this.operations) {
            currentPoints = op.apply(currentPoints);
        }
        this.points = currentPoints;
    }
}`}
